window.VD=window.VD||{};window.VD["audi/r8-42"]={"r8-42-activate-aux-in-socket-retrofit":"<p><strong>Purpose </strong>: to activate the AUX-IN input. After installing the jack plug on the connector or a Bluetooth kit on the RNS-E, you can select AUX-IN in Source. For a BT module, if you have the AMI option, disable it. (Retrofit)   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Modify the penultimate digit by adding <strong>4</strong>(e.g. replace <strong>xxxxx1x</strong>with <strong>xxxxx5x</strong>). </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_tt_8j_stg37_navi_codierung_auxin-f8795b14.webp\"/></figure>","r8-42-aileron-deactivation":"<p><strong>Purpose</strong>: to disable spoiler operation. If you code the spoiler deployed or closed, it will be locked in the position after coding! Perfect for mounting a fixed tuning spoiler.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>46 – Central Conv</strong>” or “<strong>09 – Cent. Elect.</strong>”. 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/> 5 – Choose <em>Byte <strong>10</strong>: </em><br/><em>Bit <strong>3</strong>: Uncheck “Rear Spoiler Installed”.</em></p>","r8-42-aileron-lowering-on-locking":"<p><strong>Purpose</strong>: to lower the spoiler after the doors have been closed centrally.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>46 – Central Conv</strong>” <em>or</em> “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>,” then click on “<strong>Long Coding Helper</strong>.”<br/><br/><strong>5</strong> – Select <em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “Rear Spoiler Comfort Lowering via Door Lock active”</em> <em>to disable it</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-907-063-B_Module09_Byte13-b06cb7b1.webp\"/></figure>","r8-42-automatic-door-locks":"<p><strong>Purpose:</strong> to set automatic door locking from 15km/h.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>2</strong>: Check “Auto-Lock (automatic locking from 15 km/h)”. </em> </p>","r8-42-automatic-door-unlocking":"<p><strong>Purpose:</strong> to set automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“46 – Comfort module</strong>“.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on ” <strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte<strong> 0</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Auto-Unlock (unlocking after removing key from ignition)”. </em> </p>","r8-42-automatic-headlight-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_auswahl-steuergerate-rls-wws-bord-c6f10e6e.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_bordnetz_rls_autobahnlicht_regenl-c0c525c9.webp\"/></figure>","r8-42-change-rns-e-startup-screen":"<p><strong>Purpose </strong>: to change the screen display at RNS-E start-up.  </p>\n<p><strong><em><em>CAUTION (Some RNS-E settings are directly related to the selected model. It is not recommended to change the vehicle model (Line 1)). </em> </em></strong></p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“37 – Navigation</strong>” .<br/><br/><strong>4 </strong>– Click on<strong>“Codage- 07</strong>”.</p>\n<p><strong>5</strong> – Change the 2nd digit to the desired model. (ex: replace<strong>02xxxxx</strong>by<strong>01xxxxx</strong>to display the Lamborghini logo on an A3) </p>\n<p>– 1 Lamborghini Galardo<br/>– 2 <em>Audi A3 (8P)</em><br/>– 3 Audi A4 (8E) or Seat Exeo (3R)<br/>– 4 Audi A4 Cabriolet (8H)<br/>– 5 Audi A6 (4B)<br/>– 6 Audi TT (8J)<br/>– 7 Audi R8 (42)</p>\n<p><strong>Line 2:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>” .<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 18</strong> (Start Screen) then set the value according to the desired display. <br/><br/>– 0 Standard<br/>– 1 Audi S3 (8P)<br/>– 2 Audi S4 (8E)<br/>– 3 Audi RS4, (8E)<br/>– 4 Audi TT (8J)<br/>– 5 Audi R8 (42)<br/>– 7 Audi TT S (8J)<br/>– 8 Audi TT RS (8J)<br/>– 9 Audi R8 GT (<em>42</em>)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel18-4f78df82.webp\"/></figure>","r8-42-deactivate-windshield-washer-indicator":"<p><strong>Purpose:</strong> to deactivate the windshield washer indicator on the ODB (on-board computer).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4 </strong>– Click on “<strong>Coding – 07 </strong>”.  </p>\n<p><em><strong>5</strong> – <em>Subtract <strong>5 from the </strong>last coding digit (00xxxx<strong>?</strong>)</em></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-A3-8P-ed05618a.webp\"/></figure>\n<p>Example: 0000148 -&gt; 0000143</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/laveglace-edc83d4f.webp\"/></figure>","r8-42-delete-belt-alarm":"<p><strong>Purpose:</strong> To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4 </strong>– Click on “<strong>Coding – 07 </strong>”.  </p>\n<p><em>Put<strong> 0</strong> in the penultimate digit of the code (00xxx<strong>?</strong>x)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/17-Instruments-Coding-A3-8P-ed05618a.webp\"/></figure>\n<p>Example: 0000143 -&gt; 0000103</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","r8-42-disable-automatic-aileron-folding":"<p><strong>Purpose</strong>: to deactivate automatic aileron folding when the aileron has been deployed manually.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>46 – Central Conv</strong>” <em>or</em> “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/> 5 – Choose <em>Byte <strong>13</strong>: </em><br/><em>Bit <strong>6</strong>: Uncheck “Rear Spoiler Automatic Lowering after Manual Raising inactive”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-907-063-B_Module09_Byte13-b06cb7b1.webp\"/></figure>","r8-42-disable-plate-light-control-odb-led-error":"<p><strong>Purpose:</strong> Disables license plate light control. Useful when installing LED bulbs without resistance or for error prevention.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>By year :</p>\n<p><em>Byte <strong>18</strong>: </em> <br/><em>Bit <strong>0</strong>: Uncheck “Cold Diagnosis Licence Plate Lights active”.</em></p>\n<p><strong>Or</strong></p>\n<p>Byte <strong>23</strong>:  </p>\n<p>Bit <strong>6</strong>: Uncheck: “Lamp Monitoring (Cold) License Plate Lamps Active”.  </p>\n<p>And <em>Byte <strong>17 </strong>: </em><br/><em>Bit <strong>7</strong>: Uncheck “License Plate Light w/o Pulse Width Modulation (PWM) [LED Light]”.</em></p>","r8-42-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Depending on the year :</p>\n<p><em>Byte <strong>17</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flash Light active”.</em></p>\n<p><strong>Or</strong></p>\n<p><em>Byte <strong>16</strong>: </em><br/><em>Bit <strong>1</strong>: Check “Emergency Brake Flashing via Brake Light active” (to activate brake lights)</em><br/><em>Bit <strong>2</strong>: Check “Emergency Brake Flashing via Turn Signal active” (to activate turn signals)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/emergencybreakg6-7e26fa37.webp\"/></figure>","r8-42-lap-timer":"<p><strong>Purpose:</strong> to add the stopwatch to the ODB (on-board computer).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as specified in the bubble (x?x).</em></p>\n<p><em>Example: original value 001: change to 011</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/11-Tuto-Vagcom-A3-8P-Check-des-Aiguilles-S3-ET-RS3-2ab59919.webp\"/></figure>","r8-42-lock-rns-e-cd-dvd-eject-button":"<p><strong>Purpose</strong>: To lock/unlock the RNS-E’s CD/DVD eject button.  </p>\n<p><em>Protection against theft of your navigation DVD.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>37 – Navigation</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 67</strong> </em>then set the value to <strong>255</strong> <em>(Eject Button locked i.e. (Rental Car))</em></p>\n<p><em>Restart RNS-E.</em></p>\n<p>To eject the CD/DVD, set the value to <strong>0</strong> for normal use of the button, or <strong>1</strong> for immediate ejection.  </p>","r8-42-maintain-decrease-drl-intensity-with-turn-signals":"<p><strong>Purpose:</strong> to maintain or reduce the intensity of the daytime running lights (DRL) with the indicators.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>8</strong>: </em><br/><em>Bit <strong>7</strong>: “Daytime Running Light (DRL) Desactivation while blinking active”.</em></p>\n<p>Uncheck to maintain intensity or Check to lower intensity.</p>\n<p><strong>For models from 2010 :</strong></p>\n<p><em>Byte <strong>15</strong>: </em><br/><em>Bit <strong>3</strong>: “Daytime Running Light (DRL) inactive with Turn Signals active”.</em></p>\n<p>Uncheck to maintain intensity or Check to lower intensity.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audittled-f128febf.webp\"/></figure>","r8-42-microphone-sensitivity-adjustment":"<p><strong>Purpose:</strong> Adjusts microphone intensity.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“77 – Telephone</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose Channel <strong>131</strong>.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose a value expressed in<strong>“dB</strong>” (default value<strong>“0 dB</strong>”) then validate.<br/></p>","r8-42-needle-check":"<p><strong>Purpose:</strong> activates needle sweep when the car is started. (Needle Sweep)   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as indicated in the bubble (xx?).</em></p>\n<p><em><em>Example: </em>original value 010: change to 011</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/11-Tuto-Vagcom-A3-8P-Check-des-Aiguilles-S3-ET-RS3-2ab59919.webp\"/></figure>","r8-42-odb-speed-ratio-display":"<p><strong>Purpose:</strong> to activate the gear display on the on-board computer (for manual gearboxes).   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>10 – Adaptation</strong> </p>\n<p><strong>5</strong> – Select<strong> Channel 36</strong> <em>“Special Functions”</em><br/><em>Add <strong>+1</strong> to the existing value as specified in the tooltip (?xx).</em></p>\n<p><em><em>Example:</em></em> <em>original value 011: change to 111</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi-tt-rapport-4384918e.webp\"/></figure>","r8-42-rns-e-speed-limit-display":"<p><strong>Purpose </strong>: to display the speed limit on the RNS-E navigation screen.  </p>\n<p><strong><em>ATTENTION: requires RNS-E version 193</em></strong></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong><br/></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on<strong>“37 – Navigation</strong>”.<br/><br/> 4<strong>– </strong>Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select <strong>Channel 17</strong> (Speed Display) then set the value according to the desired display. <br/><br/>Set the value according to the desired display<em><br/>0</em><em>– no option (display disabled)<br/></em> 1<em>– option on, off (speed display)<br/></em> 2<em>– option on, off, 5km/h, 10km/h, 15km/h, 20km/h (speed display + overrun warning)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8P0-035-193-G_Module37_Adaptation_Channel17-6e590288.webp\"/></figure>\n<p><em>Don’t forget to restart the RNS-E, by pressing the power button for more than 40s.</em></p>","r8-42-synchronized-mirror-adjustment":"<p><strong>Purpose </strong>: Activates synchronous adjustment of exterior mirrors. When the mirror setting is changed, the second mirror is moved synchronously.   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Power station</strong>”.</p>\n<p><strong>4 </strong>– Click on<strong>“Coding – 07</strong>” then on “<strong>Long Coding Helper”</strong>.</p>\n<p><em>Byte <strong>08</strong>: </em> Check Bit <strong>6</strong> <br/></p>","r8-42-vehicle-lock-unlock-beeps":"<p><strong>Purpose</strong>: Enables vehicle lock/unlock confirmation with beeps (alarm) and adds beep selection menu to ODB (MFA).  </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>05 </strong>: </em><br/><em>Bit <strong>1</strong>: Check “Locking Confirmation via Horn active”.</em><br/><em>Bit <strong>2</strong>: Uncheck “Horn Confirmation Adaptation blocked (Adaptation Channel 010/011 &amp; MFA+/FIS)”.</em><br/><em>Bit <strong>4</strong>: Check “Unlocking Confirmation via Horn active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng6-2ffc7685.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/horng62-14ab4a90.webp\"/></figure>"};
